reply:
```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment> a owl:Ontology ;
    rdfs:comment "An OWL ontology of educational assessment concepts derived strictly from a given corpus. Where the corpus presents conflicting classification claims, both are encoded and the tension is noted in rdfs:comment, even where this produces classes that are jointly unsatisfiable under OWL DL semantics." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

ea:Assessment a owl:Class ;
    rdfs:label "Assessment" ;
    skos:altLabel "educational evaluation" ;
    rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning. Often used interchangeably with 'test' but not limited to tests." .

ea:Test a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Test" ;
    skos:altLabel "examination", "exam" ;
    rdfs:comment "An educational assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness, or classification. Note: the corpus also uses 'evaluation' as a synonym both for Test and, elsewhere, for Assessment generally -- a terminological tension noted here." .

ea:PsychometricProperty a owl:Class ;
    rdfs:label "Psychometric Property" .

ea:Validity a owl:Class ; rdfs:subClassOf ea:PsychometricProperty .
ea:Reliability a owl:Class ; rdfs:subClassOf ea:PsychometricProperty .

ea:TestItem a owl:Class ; rdfs:label "Test Item" .
ea:Rubric a owl:Class ; rdfs:label "Rubric" .
ea:GradingMethod a owl:Class ; rdfs:label "Grading Method" .
ea:Feedback a owl:Class ; rdfs:label "Feedback" .
ea:Learning a owl:Class ; rdfs:label "Learning" .
ea:LearningOutcome a owl:Class ; rdfs:label "Learning Outcome" .
ea:LearningOutcomeTaxonomy a owl:Class ; rdfs:label "Learning Outcome Taxonomy" .
ea:Portfolio a owl:Class ; rdfs:label "Portfolio" .
ea:EducationalApproach a owl:Class ; rdfs:label "Educational Approach" .
ea:TeacherEvaluationMeasure a owl:Class ; rdfs:label "Teacher Evaluation Measure" .
ea:AssessmentQualityIssue a owl:Class ; rdfs:label "Assessment Quality Issue" .
ea:Proficiency a owl:Class ; rdfs:label "Proficiency" .
ea:NormGroup a owl:Class ; rdfs:label "Norm Group" ; skos:altLabel "norming group" .
ea:AnswerOption a owl:Class ; rdfs:label "Answer Option" .
ea:TransferOfLearning a owl:Class ; rdfs:label "Transfer of Learning" .

#################################################################
# GENERIC OBJECT / DATATYPE PROPERTIES
#################################################################

ea:hasRubric a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Rubric .
ea:isRubricOf a owl:ObjectProperty ; owl:inverseOf ea:hasRubric .

ea:hasLearningOutcome a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:LearningOutcome .
ea:isLearningOutcomeOf a owl:ObjectProperty ; owl:inverseOf ea:hasLearningOutcome .

ea:hasTestItem a owl:ObjectProperty ; rdfs:domain ea:Test ; rdfs:range ea:TestItem .
ea:isItemOf a owl:ObjectProperty ; owl:inverseOf ea:hasTestItem .

ea:hasValidityEvidence a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Validity .
ea:hasReliabilityEvidence a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Reliability .

ea:hasOption a owl:ObjectProperty ; rdfs:domain ea:TestItem ; rdfs:range ea:AnswerOption .
ea:hasKey a owl:ObjectProperty ; rdfs:subPropertyOf ea:hasOption ; rdfs:domain ea:TestItem ; rdfs:range ea:AnswerOption .

ea:hasNormGroup a owl:ObjectProperty, owl:FunctionalProperty ; rdfs:domain ea:NormReferencedTest ; rdfs:range ea:NormGroup .

ea:hasPortfolio a owl:ObjectProperty ; rdfs:domain ea:PortfolioBasedAssessment ; rdfs:range ea:Portfolio .

ea:hasReliabilityCoefficient a owl:DatatypeProperty ; rdfs:domain ea:Reliability ; rdfs:range xsd:decimal ;
    rdfs:comment "Ranges from 0 (completely unreliable) to 1 (completely reliable)." .

ea:hasItemCount a owl:DatatypeProperty ; rdfs:domain ea:Test ; rdfs:range xsd:integer .

ea:hasCutScore a owl:DatatypeProperty ; rdfs:domain ea:CriterionReferencedTest ; rdfs:range xsd:decimal ;
    rdfs:comment "The minimum score required to pass ('mastery test'); the criterion itself is the content domain, not the cut score." .

#################################################################
# AXIS 1: PURPOSE  (Placement / Formative / Summative / Diagnostic)
#################################################################

ea:PurposeCategory a owl:Class .
ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:PurposeCategory owl:disjointUnionOf ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:PurposeCategory .

ea:PlacementAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Placement Assessment" ;
    skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test (TKT)" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] ;
    rdfs:comment "Used to place students according to prior achievement, generally not graded. Conducted before instruction to establish a baseline. NOTE TENSION: a separate Glossary passage treats 'Pre-assessment' (see ea:PreAssessment) as a distinct sibling kind of assessment rather than a synonym of Placement assessment." .

ea:FormativeAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Formative Assessment" ;
    skos:altLabel "educative assessment", "assessment for learning", "classroom assessment" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] ;
    rdfs:comment "Carried out throughout a course to monitor learning and provide ongoing feedback; generally not graded; low-stakes." .

ea:SummativeAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Summative Assessment" ;
    skos:altLabel "assessment of learning" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] ;
    rdfs:comment "Carried out at the end of a course or project; typically graded; used to assign a course grade." .

ea:DiagnosticAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:label "Diagnostic Assessment" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] .

ea:DiagnosticAssessment rdfs:subClassOf ea:FormativeAssessment ;
    rdfs:comment "TENSION: one passage lists Placement, Formative, Summative and Diagnostic as four coordinate, mutually exclusive categories (modeled via the disjoint hasPurpose value-partition above, which, combined with hasPurpose being functional, entails DiagnosticAssessment is disjoint from FormativeAssessment). Another passage states 'A common form of formative assessment is diagnostic assessment', i.e. DiagnosticAssessment subClassOf FormativeAssessment. Both axioms are asserted; jointly they entail that ea:DiagnosticAssessment is unsatisfiable, which faithfully reflects the unresolved conflict in the corpus." .

#################################################################
# AXIS 2: RESPONSE TYPE (Objective / Subjective) -- for Assessment
#################################################################

ea:ResponseTypeCategory a owl:Class .
ea:ObjectiveResponseType a owl:Class ; rdfs:subClassOf ea:ResponseTypeCategory .
ea:SubjectiveResponseType a owl:Class ; rdfs:subClassOf ea:ResponseTypeCategory .
ea:ResponseTypeCategory owl:disjointUnionOf ( ea:ObjectiveResponseType ea:SubjectiveResponseType ) .

ea:hasResponseType a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:ResponseTypeCategory .

ea:ObjectiveAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:ObjectiveResponseType ] ) ] ;
    rdfs:comment "A form of questioning that has a single correct answer." .

ea:SubjectiveAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:SubjectiveResponseType ] ) ] ;
    rdfs:comment "A form of questioning that may have more than one correct answer." .

#################################################################
# AXIS 3: REFERENCE FRAME (Criterion / Norm / Ipsative)
#################################################################

ea:ReferenceFrameCategory a owl:Class .
ea:CriterionReference a owl:Class ; rdfs:subClassOf ea:ReferenceFrameCategory .
ea:NormReference a owl:Class ; rdfs:subClassOf ea:ReferenceFrameCategory .
ea:IpsativeReference a owl:Class ; rdfs:subClassOf ea:ReferenceFrameCategory .
ea:ReferenceFrameCategory owl:disjointUnionOf ( ea:CriterionReference ea:NormReference ea:IpsativeReference ) .

ea:hasReferenceFrame a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:ReferenceFrameCategory .

ea:CriterionReferencedAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    skos:altLabel "standards-based assessment" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasReferenceFrame ; owl:someValuesFrom ea:CriterionReference ] ) ] ;
    rdfs:comment "Candidates measured against defined, objective criteria, e.g. a driving test." .

ea:NormReferencedAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasReferenceFrame ; owl:someValuesFrom ea:NormReference ] ) ] ;
    rdfs:comment "Relative to the student body taking it; colloquially 'grading on the curve', e.g. an IQ test." .

ea:IpsativeAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasReferenceFrame ; owl:someValuesFrom ea:IpsativeReference ] ) ] ;
    rdfs:comment "Self-comparison, either over time in the same domain or comparative to other domains within the same student." .

ea:CriterionReferencedTest a owl:Class ;
    rdfs:subClassOf ea:Test ;
    skos:altLabel "CRT", "standards-based test" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Test
        [ a owl:Restriction ; owl:onProperty ea:hasReferenceFrame ; owl:someValuesFrom ea:CriterionReference ] ) ] .

ea:NormReferencedTest a owl:Class ;
    rdfs:subClassOf ea:Test ;
    skos:altLabel "NRT" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Test
        [ a owl:Restriction ; owl:onProperty ea:hasReferenceFrame ; owl:someValuesFrom ea:NormReference ] ) ] .

#################################################################
# AXIS 4: FORMALITY (Formal / Informal)
#################################################################

ea:FormalityCategory a owl:Class .
ea:FormalFormality a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalFormality a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:FormalityCategory owl:disjointUnionOf ( ea:FormalFormality ea:InformalFormality ) .

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:FormalityCategory .

ea:FormalAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalFormality ] ) ] ;
    rdfs:comment "Usually implies a written document and is given a numerical score or grade." .

ea:InformalAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalFormality ] ) ] ;
    rdfs:comment "Does not contribute to a student's final grade; e.g. observation, checklists, rating scales." .

#################################################################
# AXIS 5: LOCUS (Internal / External)
#################################################################

ea:LocusCategory a owl:Class .
ea:InternalLocus a owl:Class ; rdfs:subClassOf ea:LocusCategory .
ea:ExternalLocus a owl:Class ; rdfs:subClassOf ea:LocusCategory .
ea:LocusCategory owl:disjointUnionOf ( ea:InternalLocus ea:ExternalLocus ) .

ea:hasLocus a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:LocusCategory .

ea:InternalAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:InternalLocus ] ) ] ;
    rdfs:comment "Set and marked by the school (teachers)." .

ea:ExternalAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:ExternalLocus ] ) ] ;
    rdfs:comment "Set by a governing body and marked by unbiased personnel." .

#################################################################
# AXIS 6: STANDARDIZATION (for Test)
#################################################################

ea:StandardizationCategory a owl:Class .
ea:StandardizedCondition a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedCondition a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:StandardizationCategory owl:disjointUnionOf ( ea:StandardizedCondition ea:NonStandardizedCondition ) .

ea:hasStandardization a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Test ; rdfs:range ea:StandardizationCategory .

ea:StandardizedTest a owl:Class ;
    rdfs:subClassOf ea:Test ;
    skos:altLabel "standardized assessment" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Test
        [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:StandardizedCondition ] ) ] ;
    rdfs:comment "Administered and scored in a consistent/standard manner for all test takers." .

ea:NonStandardizedTest a owl:Class ;
    rdfs:subClassOf ea:Test ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Test
        [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:NonStandardizedCondition ] ) ] ;
    rdfs:comment "Flexible in scope and format, variable in difficulty." .

# Standardized-test subtypes (coordinate list)
ea:AchievementTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:AptitudeTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:CollegeAdmissionsTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
[] a owl:AllDisjointClasses ;
   owl:members ( ea:AchievementTest ea:AptitudeTest ea:CollegeAdmissionsTest ea:InternationalComparisonTest ea:PsychologicalTest ) .

ea:ComputerAdaptiveTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
    rdfs:comment "E.g. the Graduate Record Exam (GRE)." .

#################################################################
# AXIS 7: STAKES (High / Low)
#################################################################

ea:StakesCategory a owl:Class .
ea:HighStakesLevel a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:LowStakesLevel a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:StakesCategory owl:disjointUnionOf ( ea:HighStakesLevel ea:LowStakesLevel ) .

ea:hasStakesLevel a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Test ; rdfs:range ea:StakesCategory .

ea:HighStakesTest a owl:Class ;
    rdfs:subClassOf ea:Test ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Test
        [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:HighStakesLevel ] ) ] ;
    rdfs:comment "A test with a desired reward for good performance or used to make important decisions about students, educators, schools or districts." .

ea:LowStakesTest a owl:Class ;
    rdfs:subClassOf ea:Test ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Test
        [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:LowStakesLevel ] ) ] .

ea:CompetitiveExamination a owl:Class ;
    rdfs:subClassOf ea:NormReferencedTest, ea:HighStakesTest ;
    rdfs:comment "Candidates ranked by grade/percentile; top n candidates pass. Example: civil-service examinations." .

#################################################################
# AXIS 8: ADMINISTRATION MODE
#################################################################

ea:AdministrationModeCategory a owl:Class .
ea:WrittenMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .
ea:OnScreenMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .
ea:PracticalMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .
ea:VerbalMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .
ea:AdministrationModeCategory owl:disjointUnionOf ( ea:WrittenMode ea:OnScreenMode ea:PracticalMode ea:VerbalMode ) .

ea:hasAdministrationMode a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Test ; rdfs:range ea:AdministrationModeCategory .

ea:WrittenTest a owl:Class ; rdfs:subClassOf ea:Test ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Test
        [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:WrittenMode ] ) ] .
ea:OnScreenTest a owl:Class ; rdfs:subClassOf ea:Test ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Test
        [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:OnScreenMode ] ) ] .
ea:PracticalTest a owl:Class ; rdfs:subClassOf ea:Test ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Test
        [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:PracticalMode ] ) ] .
ea:VerbalTest a owl:Class ; rdfs:subClassOf ea:Test ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Test
        [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:VerbalMode ] ) ] .

#################################################################
# PERFORMANCE / AUTHENTIC ASSESSMENT
#################################################################

ea:PerformanceBasedAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment ;
    rdfs:comment "Requires students to solve real-world problems or produce something with real-world application; similar to, but not asserted equal to, summative assessment." .

ea:OutcomeFormCategory a owl:Class .
ea:ProductOutcome a owl:Class ; rdfs:subClassOf ea:OutcomeFormCategory .
ea:PerformanceOutcome a owl:Class ; rdfs:subClassOf ea:OutcomeFormCategory .
ea:OutcomeFormCategory owl:disjointUnionOf ( ea:ProductOutcome ea:PerformanceOutcome ) .

ea:hasOutcomeForm a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:PerformanceBasedAssessment ; rdfs:range ea:OutcomeFormCategory .

ea:ProductOutcomeAssessment a owl:Class ; rdfs:subClassOf ea:PerformanceBasedAssessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:PerformanceBasedAssessment
        [ a owl:Restriction ; owl:onProperty ea:hasOutcomeForm ; owl:someValuesFrom ea:ProductOutcome ] ) ] ;
    rdfs:comment "E.g. a painting, portfolio, paper, or exhibition." .

ea:PerformanceOutcomeAssessment a owl:Class ; rdfs:subClassOf ea:PerformanceBasedAssessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:PerformanceBasedAssessment
        [ a owl:Restriction ; owl:onProperty ea:hasOutcomeForm ; owl:someValuesFrom ea:PerformanceOutcome ] ) ] ;
    rdfs:comment "E.g. a speech, athletic skill, musical recital, or reading." .

ea:ContextCategory a owl:Class .
ea:RealisticContext a owl:Class ; rdfs:subClassOf ea:ContextCategory .
ea:AcademicContext a owl:Class ; rdfs:subClassOf ea:ContextCategory .
ea:ContextCategory owl:disjointUnionOf ( ea:RealisticContext ea:AcademicContext ) .

ea:hasAssessmentContext a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Assessment ; rdfs:range ea:ContextCategory .

ea:AuthenticAssessment a owl:Class ;
    rdfs:subClassOf ea:Assessment, ea:PerformanceBasedAssessment ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
        [ a owl:Restriction ; owl:onProperty ea:hasAssessmentContext ; owl:someValuesFrom ea:RealisticContext ] ) ] ;
    rdfs:comment "Measurement of accomplishments within a realistic, practical context relevant outside the school setting. A Glossary passage states 'Performance assessments may also be called authentic assessments', hence the added subClassOf ea:PerformanceBasedAssessment; the main-article passage, however, defines it independently via realistic context, so both are retained." .

ea:PerformanceTest a owl:Class ;
    rdfs:subClassOf ea:Test, ea:PerformanceBasedAssessment ;
    rdfs:comment "Requires an examinee to actually perform a task or activity, e.g. a behind-the-wheel driving test." .

#################################################################
# TEST ITEM TAXONOMY
#################################################################

ea:ItemFormatCategory a owl:Class .
ea:ObjectiveItemFormat a owl:Class ; rdfs:subClassOf ea:ItemFormatCategory .
ea:SubjectiveItemFormat a owl:Class ; rdfs:subClassOf ea:ItemFormatCategory .
ea:ItemFormatCategory owl:disjointUnionOf ( ea:ObjectiveItemFormat ea:SubjectiveItemFormat ) .

ea:hasItemFormat a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:TestItem ; rdfs:range ea:ItemFormatCategory .

ea:ObjectiveItem a owl:Class ; rdfs:subClassOf ea:TestItem ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
        [ a owl:Restriction ; owl:onProperty ea:hasItemFormat ; owl:someValuesFrom ea:ObjectiveItemFormat ] ) ] .

ea:SubjectiveItem a owl:Class ; rdfs:subClassOf ea:TestItem ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
        [ a owl:Restriction ; owl:onProperty ea:hasItemFormat ; owl:someValuesFrom ea:SubjectiveItemFormat ] ) ] .

ea:OpennessCategory a owl:Class .
ea:ClosedEndedness a owl:Class ; rdfs:subClassOf ea:OpennessCategory .
ea:OpenEndedness a owl:Class ; rdfs:subClassOf ea:OpennessCategory .
ea:OpennessCategory owl:disjointUnionOf ( ea:ClosedEndedness ea:OpenEndedness ) .

ea:hasOpenness a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:TestItem ; rdfs:range ea:OpennessCategory .

ea:ClosedEndedItem a owl:Class ; rdfs:subClassOf ea:TestItem ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
        [ a owl:Restriction ; owl:onProperty ea:hasOpenness ; owl:someValuesFrom ea:ClosedEndedness ] ) ] .
ea:OpenEndedItem a owl:Class ; rdfs:subClassOf ea:TestItem ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
        [ a owl:Restriction ; owl:onProperty ea:hasOpenness ; owl:someValuesFrom ea:OpenEndedness ] ) ] .

# Objective item kinds (coordinate list)
ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:MultipleChoiceItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem, ea:ClosedEndedItem ;
    skos:altLabel "MCQ", "multiple choice question", "One-Best-Answer question" ;
    rdfs:comment "Consists of a stem and alternative answers (options); the correct option is the key, incorrect ones are distractors. Only one answer may be keyed as correct." .
ea:MultipleResponseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ;
    rdfs:comment "More than one answer may be keyed as correct, contrasting with MultipleChoiceItem." .
ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .

[] a owl:AllDisjointClasses ;
   owl:members ( ea:TrueFalseItem ea:MultipleChoiceItem ea:MultipleResponseItem ea:MatchingItem ) .

ea:TrueFalseItem rdfs:subClassOf ea:MultipleChoiceItem ;
    rdfs:comment "TENSION: elsewhere, objective question types (true/false, multiple-choice, multiple-response, matching) are listed as coordinate, mutually exclusive alternatives (modeled above via AllDisjointClasses). A separate passage on 'families of multiple-choice questions' states the 'True/False question' is a family of multiple-choice item. Both claims are modeled, jointly entailing ea:TrueFalseItem is unsatisfiable." .

ea:KeyMultiplicityCategory a owl:Class .
ea:SingleKey a owl:Class ; rdfs:subClassOf ea:KeyMultiplicityCategory .
ea:MultipleKey a owl:Class ; rdfs:subClassOf ea:KeyMultiplicityCategory .
ea:KeyMultiplicityCategory owl:disjointUnionOf ( ea:SingleKey ea:MultipleKey ) .

ea:hasKeyMultiplicity a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:TestItem ; rdfs:range ea:KeyMultiplicityCategory .

ea:MultipleChoiceItem rdfs:subClassOf
    [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:cardinality "1"^^xsd:nonNegativeInteger ] .
ea:MultipleResponseItem rdfs:subClassOf
    [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:minCardinality "2"^^xsd:nonNegativeInteger ] .

# Subjective item kinds (coordinate list)
ea:ExtendedResponseItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .
ea:EssayItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem, ea:OpenEndedItem ;
    skos:altLabel "free response question", "FRQ" .
ea:FreeResponseItem owl:equivalentClass ea:EssayItem .
[] a owl:AllDisjointClasses ;
   owl:members ( ea:ExtendedResponseItem ea:EssayItem ) .

ea:FillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:TestItem .

#################################################################
# SPECIFIC TEST / EXAMINATION KINDS BY TIMING
#################################################################

ea:MidtermExamination a owl:Class ; rdfs:subClassOf ea:Test ;
    rdfs:subClassOf [ a owl:Class ; owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] ;
    rdfs:comment "Given near the middle of an academic term; corpus states it is 'a type of formative or summative assessment', modeled disjunctively." .

ea:FinalExamination a owl:Class ; rdfs:subClassOf ea:Test, ea:SummativeAssessment ;
    rdfs:comment "Culminating review/assessment at the end of a course." .

ea:Quiz a owl:Class ; rdfs:subClassOf ea:Test, ea:FormativeAssessment ;
    rdfs:comment "A brief assessment, usually of low stakes, used formatively." .

#################################################################
# SECOND 'ASSESSMENT TYPES' GLOSSARY LIST
#################################################################

ea:PreAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
    rdfs:comment "Administered before a lesson/unit/program to establish a baseline or readiness. TENSION: elsewhere equated with ea:PlacementAssessment ('Placement evaluation, also referred to as pre-assessment...'), while the Glossary presents Pre-assessment, Placement assessment, Formative, Summative, Interim and Screening assessment as six coordinate sibling kinds." .

ea:InterimAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
    rdfs:subClassOf [ a owl:Class ; owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] ;
    rdfs:comment "Periodic/benchmark assessment; 'some educators consider interim tests to be formative... but others may consider them to be summative' -- modeled disjunctively." .

ea:ScreeningAssessment a owl:Class ; rdfs:subClassOf ea:Assessment .

ea:CommonAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
    rdfs:subClassOf [ a owl:Class ; owl:unionOf ( ea:FormativeAssessment ea:SummativeAssessment ) ] ;
    rdfs:comment "Used across a school/department for consistency; 'may be formative or summative'." .

ea:PortfolioBasedAssessment a owl:Class ; rdfs:subClassOf ea:Assessment .

[] a owl:AllDisjointClasses ;
   owl:members ( ea:PreAssessment ea:PlacementAssessment ea:FormativeAssessment ea:SummativeAssessment ea:InterimAssessment ea:ScreeningAssessment ) .

#################################################################
# RUBRIC TAXONOMY
#################################################################

ea:RubricTypeCategory a owl:Class .
ea:HolisticRubricType a owl:Class ; rdfs:subClassOf ea:RubricTypeCategory .
ea:AnalyticRubricType a owl:Class ; rdfs:subClassOf ea:RubricTypeCategory .
ea:DevelopmentalRubricType a owl:Class ; rdfs:subClassOf ea:RubricTypeCategory .
ea:RubricTypeCategory owl:disjointUnionOf ( ea:HolisticRubricType ea:AnalyticRubricType ea:DevelopmentalRubricType ) .

ea:hasRubricType a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Rubric ; rdfs:range ea:RubricTypeCategory .

ea:HolisticRubric a owl:Class ; rdfs:subClassOf ea:Rubric ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
        [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:HolisticRubricType ] ) ] ;
    rdfs:comment "Provides an overall rating for a piece of work, considering all aspects." .

ea:AnalyticRubric a owl:Class ; rdfs:subClassOf ea:Rubric ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
        [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:AnalyticRubricType ] ) ] ;
    rdfs:comment "Evaluates various dimensions or components separately." .

ea:DevelopmentalRubric a owl:Class ; rdfs:subClassOf ea:Rubric ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
        [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:DevelopmentalRubricType ] ) ] .

ea:DevelopmentalRubric rdfs:subClassOf ea:AnalyticRubric ;
    rdfs:comment "TENSION: 'Rubrics can be classified as holistic, analytic, or developmental' presents three coordinate (and, via the disjoint value-partition above, mutually exclusive) kinds, but the same passage immediately states 'Developmental rubrics, a subset of analytical rubrics'. Both are modeled; jointly they entail ea:DevelopmentalRubric is unsatisfiable." .

ea:TraitInformedScoring a owl:Class ; rdfs:subClassOf ea:GradingMethod ;
    rdfs:comment "Trains raters to score against a scoring guide with multiple traits; close to analytic scoring, but remains holistic in that raters consider all traits before giving a single final score." .

ea:GradingApproachCategory a owl:Class .
ea:HolisticGradingApproach a owl:Class ; rdfs:subClassOf ea:GradingApproachCategory .
ea:AnalyticGradingApproach a owl:Class ; rdfs:subClassOf ea:GradingApproachCategory .
ea:GradingApproachCategory owl:disjointUnionOf ( ea:HolisticGradingApproach ea:AnalyticGradingApproach ) .

ea:hasGradingApproach a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:GradingMethod ; rdfs:range ea:GradingApproachCategory .

ea:HolisticGrading a owl:Class ; rdfs:subClassOf ea:GradingMethod ;
    skos:altLabel "holistic scoring", "nonreductionist grading" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:GradingMethod
        [ a owl:Restriction ; owl:onProperty ea:hasGradingApproach ; owl:someValuesFrom ea:HolisticGradingApproach ] ) ] ;
    rdfs:comment "Bases a grade on a paper's overall quality, treating the composition as a whole." .

ea:AnalyticGrading a owl:Class ; rdfs:subClassOf ea:GradingMethod ;
    owl:equivalentClass [ owl:intersectionOf ( ea:GradingMethod
        [ a owl:Restriction ; owl:onProperty ea:hasGradingApproach ; owl:someValuesFrom ea:AnalyticGradingApproach ] ) ] ;
    rdfs:comment "Takes more factors into account, criterion-by-criterion judgments." .

#################################################################
# VALIDITY TAXONOMY
#################################################################

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "logical validity" .
ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "criterion-related validity" .
ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .

ea:Validity owl:disjointUnionOf ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity ea:FaceValidity ea:ConsequentialValidity ) .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:FaceValidity rdfs:subClassOf ea:ConstructValidity .
ea:ConsequentialValidity rdfs:subClassOf ea:ConstructValidity ;
    rdfs:comment "TENSION: one passage enumerates content, criterion, construct, face and consequential validity as coordinate categories of validity evidence (modeled as a disjoint union of ea:Validity). Another passage states construct validity 'subsumes all other types of validity' and 'is not distinct from' the substantive theory of the measured construct (modeled as subClassOf ea:ConstructValidity for each other kind). Jointly, these axioms entail ea:ContentValidity, ea:CriterionValidity, ea:FaceValidity and ea:ConsequentialValidity are unsatisfiable, reflecting the corpus's unresolved tension." .

ea:TimingCategory a owl:Class .
ea:SimultaneousTiming a owl:Class ; rdfs:subClassOf ea:TimingCategory .
ea:LaterTiming a owl:Class ; rdfs:subClassOf ea:TimingCategory .
ea:TimingCategory owl:disjointUnionOf ( ea:SimultaneousTiming ea:LaterTiming ) .

ea:hasMeasurementTiming a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:CriterionValidity ; rdfs:range ea:TimingCategory .

ea:ConcurrentValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity ;
    owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
        [ a owl:Restriction ; owl:onProperty ea:hasMeasurementTiming ; owl:someValuesFrom ea:SimultaneousTiming ] ) ] ;
    rdfs:comment "Test data and criterion data collected at the same time." .

ea:PredictiveValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity ;
    owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
        [ a owl:Restriction ; owl:onProperty ea:hasMeasurementTiming ; owl:someValuesFrom ea:LaterTiming ] ) ] ;
    rdfs:comment "Test data collected first to predict criterion data collected at a later time." .

ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:ConstructValidity owl:disjointUnionOf ( ea:ConvergentValidity ea:DiscriminantValidity ) ;
    rdfs:comment "'Convergent and discriminant validity are the two subtypes of validity that make up construct validity.' NOTE: this disjointUnion is independent of, and in addition to, ConstructValidity's own membership in the top-level Validity disjoint union above." .

#################################################################
# RELIABILITY TAXONOMY (two independent axes)
#################################################################

ea:ReliabilityEstimationCategory a owl:Class .
ea:InterRaterMethod a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationCategory .
ea:TestRetestMethod a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationCategory .
ea:InterMethodMethod a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationCategory .
ea:InternalConsistencyMethod a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationCategory .
ea:ReliabilityEstimationCategory owl:disjointUnionOf ( ea:InterRaterMethod ea:TestRetestMethod ea:InterMethodMethod ea:InternalConsistencyMethod ) .

ea:hasReliabilityEstimationMethod a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Reliability ; rdfs:range ea:ReliabilityEstimationCategory .

ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
        [ a owl:Restriction ; owl:onProperty ea:hasReliabilityEstimationMethod ; owl:someValuesFrom ea:InterRaterMethod ] ) ] .

ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
    skos:altLabel "repeatability" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
        [ a owl:Restriction ; owl:onProperty ea:hasReliabilityEstimationMethod ; owl:someValuesFrom ea:TestRetestMethod ] ) ] .

ea:IntraRaterReliability a owl:Class ; rdfs:subClassOf ea:TestRetestReliability .

ea:InterMethodReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
    skos:altLabel "parallel-forms reliability" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
        [ a owl:Restriction ; owl:onProperty ea:hasReliabilityEstimationMethod ; owl:someValuesFrom ea:InterMethodMethod ] ) ] .

ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
        [ a owl:Restriction ; owl:onProperty ea:hasReliabilityEstimationMethod ; owl:someValuesFrom ea:InternalConsistencyMethod ] ) ] .

ea:ReliabilitySourceCategory a owl:Class .
ea:StudentFactor a owl:Class ; rdfs:subClassOf ea:ReliabilitySourceCategory .
ea:RaterFactor a owl:Class ; rdfs:subClassOf ea:ReliabilitySourceCategory .
ea:AdministrationFactor a owl:Class ; rdfs:subClassOf ea:ReliabilitySourceCategory .
ea:TestFactor a owl:Class ; rdfs:subClassOf ea:ReliabilitySourceCategory .
ea:ReliabilitySourceCategory owl:disjointUnionOf ( ea:StudentFactor ea:RaterFactor ea:AdministrationFactor ea:TestFactor ) .

ea:hasReliabilitySource a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Reliability ; rdfs:range ea:ReliabilitySourceCategory ;
    rdfs:comment "This is a second, independent classification axis for Reliability ('There are four types of reliability: student-related, rater-related, test administration-related, and test-related'), distinct from the reliability-estimation-method axis (inter-rater, test-retest, inter-method, internal-consistency) given elsewhere in the corpus." .

ea:StudentRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
        [ a owl:Restriction ; owl:onProperty ea:hasReliabilitySource ; owl:someValuesFrom ea:StudentFactor ] ) ] .
ea:RaterRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
        [ a owl:Restriction ; owl:onProperty ea:hasReliabilitySource ; owl:someValuesFrom ea:RaterFactor ] ) ] .
ea:TestAdministrationRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
        [ a owl:Restriction ; owl:onProperty ea:hasReliabilitySource ; owl:someValuesFrom ea:AdministrationFactor ] ) ] .
ea:TestRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Reliability
        [ a owl:Restriction ; owl:onProperty ea:hasReliabilitySource ; owl:someValuesFrom ea:TestFactor ] ) ] .

#################################################################
# LEARNING TAXONOMY
#################################################################

ea:FormalLearning a owl:Class ; rdfs:subClassOf ea:Learning .
ea:NonFormalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
    rdfs:comment "Organized learning outside the formal learning system, e.g. clubs, youth organizations, workshops." .
ea:InformalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
    rdfs:comment "Less structured than non-formal learning; occurs through day-to-day experience; typically does not lead to accreditation." .
ea:Learning owl:disjointUnionOf ( ea:FormalLearning ea:NonFormalLearning ea:InformalLearning ) .

#################################################################
# LEARNING OUTCOME TAXONOMY
#################################################################

ea:IntendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ; skos:altLabel "aim" .
ea:MeasuredLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ; skos:altLabel "objective" .
ea:UnintendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome .
ea:LearningOutcome owl:disjointUnionOf ( ea:IntendedLearningOutcome ea:MeasuredLearningOutcome ea:UnintendedLearningOutcome ) .

ea:BloomsTaxonomy a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
ea:StructureOfObservedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy ; skos:altLabel "SOLO" .
ea:DIKWPyramid a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
ea:ModelOfHierarchicalComplexity a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
[] a owl:AllDisjointClasses ;
   owl:members ( ea:BloomsTaxonomy ea:StructureOfObservedLearningOutcome ea:DIKWPyramid ea:ModelOfHierarchicalComplexity ) .

ea:ConstructiveAlignment a owl:Class ; rdfs:subClassOf ea:EducationalApproach ;
    rdfs:comment "Principle for devising teaching/learning activities and assessment tasks that directly address intended learning outcomes." .

#################################################################
# COMPETENCY-BASED LEARNING
#################################################################

ea:CompetencyBasedLearning a owl:Class ; rdfs:subClassOf ea:EducationalApproach ;
    skos:altLabel "proficiency-based learning", "mastery-based learning", "outcome-based learning", "performance-based education", "standards-based education" ;
    rdfs:comment "Systems of instruction, assessment, grading and reporting based on students demonstrating learned knowledge/skills, rather than seat time." .

#################################################################
# PORTFOLIO TAXONOMY
#################################################################

ea:PortfolioMediumCategory a owl:Class .
ea:DigitalMedium a owl:Class ; rdfs:subClassOf ea:PortfolioMediumCategory .
ea:PhysicalMedium a owl:Class ; rdfs:subClassOf ea:PortfolioMediumCategory .
ea:PortfolioMediumCategory owl:disjointUnionOf ( ea:DigitalMedium ea:PhysicalMedium ) .

ea:hasPortfolioMedium a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:Portfolio ; rdfs:range ea:PortfolioMediumCategory .

ea:DigitalPortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio ;
    skos:altLabel "e-portfolio", "digital portfolio" ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Portfolio
        [ a owl:Restriction ; owl:onProperty ea:hasPortfolioMedium ; owl:someValuesFrom ea:DigitalMedium ] ) ] .

ea:PhysicalPortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Portfolio
        [ a owl:Restriction ; owl:onProperty ea:hasPortfolioMedium ; owl:someValuesFrom ea:PhysicalMedium ] ) ] .

ea:CapstonePortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio ;
    rdfs:comment "Features student work completed as part of long-term/culminating projects; cross-cuts the digital/physical medium axis." .

#################################################################
# TEACHER EVALUATION MEASURES
#################################################################

ea:ValueAddedMeasure a owl:Class ; rdfs:subClassOf ea:TeacherEvaluationMeasure ;
    skos:altLabel "growth measure" ;
    rdfs:comment "Statistical estimate of a teacher's effect on student learning growth." .

ea:StudentGrowthMeasure a owl:Class ; rdfs:subClassOf ea:TeacherEvaluationMeasure ;
    rdfs:comment "TENSION: the same source passage first introduces 'Value-added measures, or growth measures' in apposition (as synonyms, captured by the skos:altLabel on ea:ValueAddedMeasure), then later states 'Student growth measures are a related -- but distinct -- method'. Both the synonymy and the distinctness claims are modeled: ea:StudentGrowthMeasure is kept as a sibling class of ea:ValueAddedMeasure rather than identified with it." .

#################################################################
# ASSESSMENT QUALITY ISSUES
#################################################################

ea:MeasurementError a owl:Class ; rdfs:subClassOf ea:AssessmentQualityIssue ;
    rdfs:comment "Discrepancy between a test score and a student's actual knowledge/abilities, or errors in collecting/calculating data." .

ea:ScoreInflation a owl:Class ; rdfs:subClassOf ea:AssessmentQualityIssue ;
    rdfs:comment "Scores increase without genuine improvement in learning." .

#################################################################
# TRANSFER OF LEARNING (two independent axes)
#################################################################

ea:TransferContextCategory a owl:Class .
ea:SimilarContext a owl:Class ; rdfs:subClassOf ea:TransferContextCategory .
ea:DifferentContext a owl:Class ; rdfs:subClassOf ea:TransferContextCategory .
ea:TransferContextCategory owl:disjointUnionOf ( ea:SimilarContext ea:DifferentContext ) .

ea:hasTransferContext a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:TransferOfLearning ; rdfs:range ea:TransferContextCategory .

ea:NearTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
        [ a owl:Restriction ; owl:onProperty ea:hasTransferContext ; owl:someValuesFrom ea:SimilarContext ] ) ] .
ea:FarTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
        [ a owl:Restriction ; owl:onProperty ea:hasTransferContext ; owl:someValuesFrom ea:DifferentContext ] ) ] .

ea:TransferValenceCategory a owl:Class .
ea:PositiveValence a owl:Class ; rdfs:subClassOf ea:TransferValenceCategory .
ea:NegativeValence a owl:Class ; rdfs:subClassOf ea:TransferValenceCategory .
ea:TransferValenceCategory owl:disjointUnionOf ( ea:PositiveValence ea:NegativeValence ) .

ea:hasTransferValence a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:TransferOfLearning ; rdfs:range ea:TransferValenceCategory .

ea:PositiveTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
        [ a owl:Restriction ; owl:onProperty ea:hasTransferValence ; owl:someValuesFrom ea:PositiveValence ] ) ] .
ea:NegativeTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning ;
    owl:equivalentClass [ owl:intersectionOf ( ea:TransferOfLearning
        [ a owl:Restriction ; owl:onProperty ea:hasTransferValence ; owl:someValuesFrom ea:NegativeValence ] ) ] .

#################################################################
# FEEDBACK
#################################################################

ea:CorrectiveFeedback a owl:Class ; rdfs:subClassOf ea:Feedback .
ea:Recast a owl:Class ; rdfs:subClassOf ea:CorrectiveFeedback ; skos:altLabel "motherese correction" .

ea:FeedbackMediumCategory a owl:Class .
ea:WrittenMedium a owl:Class ; rdfs:subClassOf ea:FeedbackMediumCategory .
ea:OralMedium a owl:Class ; rdfs:subClassOf ea:FeedbackMediumCategory .
ea:FeedbackMediumCategory owl:disjointUnionOf ( ea:WrittenMedium ea:OralMedium ) .

ea:hasFeedbackMedium a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain ea:CorrectiveFeedback ; rdfs:range ea:FeedbackMediumCategory .

ea:WrittenFeedback a owl:Class ; rdfs:subClassOf ea:CorrectiveFeedback ;
    owl:equivalentClass [ owl:intersectionOf ( ea:CorrectiveFeedback
        [ a owl:Restriction ; owl:onProperty ea:hasFeedbackMedium ; owl:someValuesFrom ea:WrittenMedium ] ) ] .
ea:OralFeedback a owl:Class ; rdfs:subClassOf ea:CorrectiveFeedback ;
    owl:equivalentClass [ owl:intersectionOf ( ea:CorrectiveFeedback
        [ a owl:Restriction ; owl:onProperty ea:hasFeedbackMedium ; owl:someValuesFrom ea:OralMedium ] ) ] .

ea:ImmediateFeedbackAssessmentTechnique a owl:Class ; rdfs:subClassOf ea:CorrectiveFeedback ;
